// deck-shots.js — screenshot every frame of a deck and check it fits.
// Works with any deck whose frames are full-viewport `.slide` sections
// (scroll-snap, as generated by this skill's html-template.md).
//
//   node scripts/deck-shots.js <file.html> <outdir> [width] [height]
//
// Chrome is located via CHROME_PATH — set it in the workspace root .env
// (see env.example) or export it in the shell before running. No hard-coded
// per-machine path.
//
// Prints, per frame, how many pixels it overflows down/right and which
// elements have text clipped by their box (scrollHeight taller than the box).
// Nonzero numbers mean the layout needs fixing — shrinking the font is not a
// fix, it is a way to hide the same problem.
//
// Requires puppeteer-core (`npm install puppeteer-core`) and a local Chrome/
// Chromium at CHROME_PATH.
const path = require('path');
const fs = require('fs');

// CHROME_PATH usually only lives in the workspace root .env — nothing else
// loads it into this process for us, so we do it ourselves (env-check.sh
// only inspects the file, it never sources it).
function loadEnv(startDir) {
  let dir = startDir;
  for (;;) {
    const hasHarness = fs.existsSync(path.join(dir, 'harness.json')) ||
      fs.existsSync(path.join(dir, 'workspace.json'));
    if (hasHarness) {
      const envPath = path.join(dir, '.env');
      if (fs.existsSync(envPath)) {
        const lines = fs.readFileSync(envPath, 'utf8').split('\n');
        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) continue;
          const idx = trimmed.indexOf('=');
          const key = trimmed.slice(0, idx).trim();
          let val = trimmed.slice(idx + 1).trim();
          if (val.length >= 2 && ((val[0] === '"' && val.endsWith('"')) || (val[0] === "'" && val.endsWith("'")))) {
            val = val.slice(1, -1);
          }
          if (process.env[key] === undefined) process.env[key] = val;
        }
      }
      return;
    }
    const parent = path.dirname(dir);
    if (parent === dir) return;
    dir = parent;
  }
}
loadEnv(__dirname);

const CHROME = process.env.CHROME_PATH;

(async () => {
  const [file, outdir, w = '1600', h = '900'] = process.argv.slice(2);
  if (!file || !outdir) {
    console.error('usage: node scripts/deck-shots.js <file.html> <outdir> [w] [h]');
    process.exit(2);
  }
  if (!CHROME) {
    console.error('CHROME_PATH не задан — укажи путь к Chrome/Chromium в .env (см. env.example)');
    process.exit(1);
  }
  if (!fs.existsSync(CHROME)) {
    console.error(`CHROME_PATH указывает на несуществующий файл: ${CHROME}`);
    process.exit(1);
  }
  let puppeteer;
  try {
    puppeteer = require('puppeteer-core');
  } catch {
    console.error('puppeteer-core не установлен: npm install puppeteer-core');
    process.exit(1);
  }
  fs.mkdirSync(outdir, { recursive: true });

  const b = await puppeteer.launch({
    executablePath: CHROME,
    headless: 'new',
    args: ['--no-sandbox', '--hide-scrollbars'],
  });
  const p = await b.newPage();
  await p.setViewport({ width: +w, height: +h, deviceScaleFactor: 2 });
  await p.goto('file://' + path.resolve(file), { waitUntil: 'networkidle0' });
  await new Promise((r) => setTimeout(r, 1200));

  const n = await p.$$eval('.slide', (els) => els.length);
  if (n === 0) {
    console.error('0 кадров найдено — скрипт ищет элементы с классом .slide');
    await b.close();
    process.exit(1);
  }
  let problems = 0;

  for (let i = 0; i < n; i++) {
    await p.evaluate((k) => {
      document.querySelectorAll('.slide')[k].scrollIntoView({ behavior: 'instant', block: 'start' });
    }, i);
    await new Promise((r) => setTimeout(r, 700));

    const m = await p.evaluate((k) => {
      const s = document.querySelectorAll('.slide')[k];
      const box = s.getBoundingClientRect();
      let bottom = -1e9, right = -1e9, lowest = '', rightmost = '';
      const clipped = [];
      s.querySelectorAll('*').forEach((el) => {
        const r = el.getBoundingClientRect();
        if (!r.width && !r.height) return;
        if (r.bottom > bottom) { bottom = r.bottom; lowest = (el.className || el.tagName).toString().slice(0, 28); }
        if (r.right > right) { right = r.right; rightmost = (el.className || el.tagName).toString().slice(0, 28); }
        // Обрезка засчитывается только если текст физически срезан рамкой, то
        // есть у самого элемента стоит overflow. У крупных заголовков с
        // line-height меньше единицы глифы законно выходят за бокс, и
        // сравнение одних высот даёт постоянный ложный крик.
        const over = el.scrollHeight - Math.ceil(r.height);
        const cs = getComputedStyle(el);
        const hidden = cs.overflowY !== 'visible' || cs.overflowX !== 'visible';
        if (el.children.length === 0 && hidden && over > 2)
          clipped.push((el.className || el.tagName).toString().slice(0, 28));
      });
      return {
        overflowBottomPx: Math.round(bottom - box.bottom),
        lowest,
        overflowRightPx: Math.round(right - box.right),
        rightmost,
        clipped: [...new Set(clipped)],
      };
    }, i);

    await p.screenshot({ path: path.join(outdir, `frame-${String(i + 1).padStart(2, '0')}.png`) });

    const bad = m.overflowBottomPx > 2 || m.overflowRightPx > 2 || m.clipped.length > 0;
    if (bad) problems++;
    console.log(
      `frame ${String(i + 1).padStart(2, '0')} ${bad ? 'PROBLEM ' : 'ok      '}` +
      ` down=${m.overflowBottomPx}px (${m.lowest}) right=${m.overflowRightPx}px (${m.rightmost})` +
      (m.clipped.length ? ` clipped: ${m.clipped.join(', ')}` : '')
    );
  }

  console.log(`\nframes: ${n}, with problems: ${problems}`);
  await b.close();
  process.exit(problems ? 1 : 0);
})();
